import{_ as o,o as e,c as d,ag as r}from"./chunks/framework.Fczl-Cb9.js";const p=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"introduction.md","filePath":"introduction.md","lastUpdated":1771746637000}'),n={name:"introduction.md"};function s(a,t,i,l,h,c){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Not a fork</p><p>cloding doesn&#39;t modify, patch, or fork any CLI tool. It&#39;s a thin configuration wrapper — zero modified binaries. Just smart routing.</p></div><p><strong>cloding</strong> is a universal wrapper that lets you run <strong>5 coding CLI tools</strong> with <strong>any model</strong> — via OpenRouter, direct API keys, or your paid subscription plan.</p><h2 id="supported-tools" tabindex="-1">Supported Tools <a class="header-anchor" href="#supported-tools" aria-label="Permalink to &quot;Supported Tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>What cloding does</th><th>Auth modes</th></tr></thead><tbody><tr><td><strong>Claude Code</strong></td><td>Routes through OpenRouter or your Anthropic API key</td><td>OpenRouter, Anthropic API, Claude Max</td></tr><tr><td><strong>Gemini CLI</strong></td><td>Routes through OpenRouter, Google API, or your Gemini plan</td><td>OpenRouter, Google API, Gemini plan</td></tr><tr><td><strong>Codex CLI</strong></td><td>Uses your ChatGPT plan or OpenAI API key</td><td>ChatGPT plan, OpenAI API</td></tr><tr><td><strong>GitHub Copilot CLI</strong></td><td>Uses your Copilot subscription</td><td>GitHub Copilot</td></tr><tr><td><strong>OpenCode</strong></td><td>Routes through OpenRouter</td><td>OpenRouter</td></tr></tbody></table><h2 id="why-cloding" tabindex="-1">Why cloding? <a class="header-anchor" href="#why-cloding" aria-label="Permalink to &quot;Why cloding?&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Claude Code (direct)</th><th>cloding + Qwen</th></tr></thead><tbody><tr><td><strong>Input cost</strong></td><td>$5.00/Mtok</td><td>$0.12/Mtok</td></tr><tr><td><strong>Output cost</strong></td><td>$25.00/Mtok</td><td>$0.75/Mtok</td></tr><tr><td><strong>Tools &amp; editing</strong></td><td>Yes</td><td>Yes</td></tr><tr><td><strong>Terminal access</strong></td><td>Yes</td><td>Yes</td></tr><tr><td><strong>Model flexibility</strong></td><td>Anthropic only</td><td>300+ models</td></tr><tr><td><strong>Docker sandboxing</strong></td><td>No</td><td>Yes</td></tr><tr><td><strong>Pipeline mode</strong></td><td>No</td><td>Yes</td></tr><tr><td><strong>30-min session</strong></td><td>~$5.00</td><td>~$0.07</td></tr></tbody></table><blockquote><p>Claude Opus 4.6 costs $5/$25 per Mtok. Qwen 3 Coder costs $0.12/$0.75 per Mtok. That&#39;s <strong>42x cheaper on input, 33x cheaper on output</strong>.</p></blockquote><h2 id="_3-auth-modes" tabindex="-1">3 Auth Modes <a class="header-anchor" href="#_3-auth-modes" aria-label="Permalink to &quot;3 Auth Modes&quot;">​</a></h2><p>Every model in cloding can be accessed through one of three authentication modes:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Suffix</th><th>What it does</th><th>Example</th></tr></thead><tbody><tr><td><strong>OpenRouter</strong></td><td><em>(none)</em> or <code>-o</code></td><td>Routes through OpenRouter — cheapest multi-model access</td><td><code>cloding -m sonnet</code></td></tr><tr><td><strong>Direct API</strong></td><td><code>-a</code></td><td>Uses your own API key for the provider</td><td><code>cloding -m sonnet-a</code></td></tr><tr><td><strong>Paid Plan</strong></td><td><code>-p</code></td><td>Links to your paid subscription (no API key needed)</td><td><code>cloding -m opus-p</code></td></tr></tbody></table><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><p><strong>5 CLI tools, 1 command</strong> — Switch between Claude Code, Gemini CLI, Codex CLI, Copilot CLI, and OpenCode with a single flag. No context switching.</p><p><strong>42x cheaper coding</strong> — Qwen 3 Coder at $0.12/Mtok vs Claude Opus at $5/Mtok. Same tools, same workflow, fraction of the cost.</p><p><strong>Docker sandboxing</strong> — Isolate any tool in a container with access only to the workspace you mount. All 5 CLIs work in Docker mode.</p><p><strong>Pipeline mode</strong> — Multi-stage coding pipelines with parallel fan-out. Assign different models to Plan, Explore, Code, and Review stages.</p><p><strong>Any OpenRouter model</strong> — Use any of 300+ models on OpenRouter by ID, or pick from built-in shortcuts with pricing.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><p>cloding is a thin wrapper that routes API calls through different providers depending on the model you choose. When you run <code>cloding</code>:</p><ol><li><strong>Pick a tool + model</strong> — Choose from 5 CLI tools and 20+ model shortcuts</li><li><strong>Auth is handled</strong> — Each model routes through OpenRouter, direct API, or your paid plan</li><li><strong>Same CLI experience</strong> — You get the exact same tool experience: file editing, terminal access, tool use</li></ol><p>That&#39;s it. No forks, no patches, no modified binaries. Just configuration.</p><h2 id="how-it-s-different" tabindex="-1">How It&#39;s Different <a class="header-anchor" href="#how-it-s-different" aria-label="Permalink to &quot;How It&#39;s Different&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>What it does</th><th>Trade-off</th></tr></thead><tbody><tr><td><strong>cloding</strong></td><td>5 CLI tools, any model, 3 auth modes</td><td>Requires at least one tool CLI installed</td></tr><tr><td><strong>aider</strong></td><td>Standalone AI coding tool</td><td>Different CLI, different tool ecosystem</td></tr><tr><td><strong>continue.dev</strong></td><td>IDE extension for AI coding</td><td>IDE-specific, not terminal-based</td></tr><tr><td><strong>Claude Code</strong></td><td>Full experience, Anthropic models only</td><td>$5/Mtok input, no model flexibility</td></tr><tr><td><strong>Gemini CLI</strong></td><td>Full experience, Google models only</td><td>No OpenRouter, no other tools</td></tr></tbody></table><p>cloding gives you the best of both worlds: mature CLI tooling with model flexibility and cost savings.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><strong><a href="/cloding/installation">Installation</a></strong> — Get cloding set up in under a minute</li><li><strong><a href="/cloding/quick-start">Quick Start</a></strong> — Run your first session</li><li><strong><a href="/cloding/models">Models &amp; Pricing</a></strong> — Compare all available models</li><li><strong><a href="/cloding/authentication">Authentication</a></strong> — Understand the 3 auth modes</li></ul>',26)])])}const g=o(n,[["render",s]]);export{p as __pageData,g as default};
